  1.-------------------------------------- LES VARIABLES EN JAVASCRIPT----------------------------------------------------

// Déclaration avec 'let' (modifiable, portée de bloc)
let age = 25;

// Déclaration avec 'const' (non modifiable, portée de bloc)
const nom = "Olamidé";

// Déclaration avec 'var' (modifiable, portée globale ou de fonction)
var pays = "France";

// Exemple de modification
age = 30; // OK
// nom = "Autre"; // Erreur : impossible de modifier une constante
