// Les variables servent à stocker des valeurs (nombres, chaînes, etc.)

Les types de données courants en JavaScript sont :
// - Number (nombres) : 42, 3.14
// - String (chaînes de caractères) : "Bonjour", 'Olamidé'
// - Boolean (booléens) : true, false
// - Array (tableaux) : [1, 2, 3], ["a", "b", "c"]
// - Object (objets) : { nom: "Olamidé", age: 25 }
// - Null (valeur nulle) : null
// - Undefined (non défini) : undefined

Les méthodes sur les chaînes de caractères
let message = "Bonjour le monde";
console.log(message.length); // Affiche la longueur de la chaîne
console.log(message.toUpperCase()); // Affiche en majuscules
console.log(message.toLowerCase()); // Affiche en minuscules
console.log(message.includes("le")); // Vrai si "le" est dans la chaîne

console.log(message.slice(0, 7)); // Affiche "Bonjour" en extrayant une partie de la chaîne
En effet pour slice, le premier argument est l'index de début (inclus) et le second est l'index de fin (exclus) c'est à dire pour slice(a,b), ça prend les caractères de l'index a jusqu'à b-1.

console.log(message.replace("monde", "tout le monde")); // Remplace "monde" par "tout le monde"
console.log(message.split(" ")); // Divise la chaîne en tableau en utilisant le paramètre passé comme séparateur. A chaque que le séparateur est rencontré, une nouvelle entrée est créée dans le tableau.
console.log(message.trim()); // Supprime les espaces au début et à la fin
console.log(message.join("-")); // Joint les éléments du tableau en une chaîne avec le séparateur spécifié
console.log(message.indexOf("le")); // Affiche l'index de la première occurrence de "le"
console.log(message.lastIndexOf("o")); // Affiche l'index de la dernière occurrence de "o"
console.log(message.charAt(0)); // Affiche le caractère à l'index 0
console.log(message.startsWith("Bon")); // Vrai si la chaîne commence par "Bon"
console.log(message.endsWith("monde")); // Vrai si la chaîne se termine par "monde"
console.log(message.repeat(2)); // Répète la chaîne 2 fois

// Les méthodes sur les tableaux
let nombres = [10, 20, 30, 40, 50];
console.log(nombres.length); // Affiche la longueur du tableau
console.log(nombres.push(60)); // Ajoute 60 à la fin du tableau
console.log(nombres.unshift(5)); // Ajoute 5 au début du tableau
console.log(nombres.pop()); // Supprime et retourne le dernier élément (60)
console.log(nombres.shift()); // Supprime et retourne le premier élément (10)
console.log(nombres.indexOf(30)); // Affiche l'index de la première occurrence de 30
console.log(nombres.lastIndexOf(20)); // Affiche l'index de la dernière occurrence de 20
console.log(nombres.slice(1, 4)); // Extrait une portion du tableau (20, 30, 40)
console.log(nombres.slice(2)); // Extrait à partir de l'index 2 jusqu'à la fin (30, 40, 50)
console.log(nombres.splice(a,b)); // À partir de l'index a, supprime b élément
console.log(nombres.splice(1, 2)); // À partir de l'index 1, supprime 2 éléments (20, 30)
console.log(nombres.splice(1, 0, 15)); // À partir de l'index 1, ne supprime rien, mais ajoute 15 (10, 15, 40, 50)
console.log(nombres.splice(2, 1, 25)); // À partir de l'index 2, supprime 1 élément (40) et ajoute 25 (10, 15, 25, 50)
console.log(nombres.reverse()); // Inverse l'ordre des éléments
console.log(nombres.sort((a, b) => a - b)); // Trie les éléments par ordre croissant
console.log(nombres.join(", ")); // Joint les éléments en une chaîne séparée par ", "
console.log(nombres.includes(25)); // Vrai si 25 est dans le tableau
console.log(nombres.forEach(num => console.log(num * 2))); // Affiche chaque nombre multiplié par 2
console.log(nombres.map(num => num * 2)); // Retourne un nouveau tableau avec chaque nombre multiplié par 2
console.log(nombres.filter(num => num > 20)); // Retourne un nouveau tableau avec les nombres supérieurs à 20
console.log(nombres.reduce((acc, num) => acc + num, 0)); // Somme de tous les nombres
reduce prend une fonction de rappel (callback) et une valeur initiale (ici 0). La fonction de rappel prend deux arguments : l'accumulateur (acc) et la valeur courante (num). À chaque itération, elle ajoute num à acc. Le résultat final est la somme de tous les éléments du tableau.
console.log(nombres.find(num => num > 25)); // Trouve le premier nombre supérieur à 25
console.log(nombres.fill(0, 1, 3)); // Remplit les index 1 à 2 avec 0 (10, 0, 0, 50)
console.log(nombres.fill(a, b, c)); // Remplit les index b à c-1 avec a
console.log(nombres.every(num => num > 0)); // Vrai si tous les nombres sont supérieurs à 0
console.log(nombres.some(num => num > 40)); // Vrai si au moins un nombre est supérieur à 40
console.log(nombres.at(-1)); // Affiche le dernier élément (50) car nombres[-1] n'est pas supporté en JS
console.log(nombres.flat()); // Aplati un tableau de tableaux en un seul tableau







