***************************************PROMISES*****************************************************
Les Promises en JavaScript sont un moyen de gérer les opérations asynchrones, telles que les appels réseau ou les opérations de lecture/écriture de fichiers. Elles représentent une valeur qui peut être disponible maintenant, dans le futur, ou jamais.
Une Promise peut être dans l'un des trois états suivants :
- En attente (pending) : l'opération asynchrone est en cours.
- Résolue (fulfilled) : l'opération s'est terminée avec succès, et une valeur est disponible.
- Rejetée (rejected) : l'opération a échoué, et une raison d'échec est disponible.
// Création d'une Promise
let maPromise = new Promise((resolve, reject) => {
  let succes = true; // Simule le succès ou l'échec de l'opération
  if (succes) {
    resolve("Opération réussie!"); // Résout la Promise avec une valeur
  } else {
    reject("Erreur lors de l'opération."); // Rejette la Promise avec une raison
  }
});
//On met dans RESOLVE la valeur que l'on veut retourner en cas de succès et dans REJECT, on met la raison de l'échec en cas d'erreur.
// Utilisation de la Promise avec then et catch
maPromise
  .then((valeur) => {
    console.log(valeur); // Affiche : Opération réussie!
    //then est appelé lorsque la Promise est résolue avec succès.Cela signifie si la Promise s'est terminée avec succès on exécute la fonction passée à then.
    // Le paramètre de la fonction fléchée de then est la valeur avec laquelle la promesse a été résolue c'est à dire la valeur passée à resolve.
    // C'est pourquoi valeur ici est "Opération réussie!".
  })
  .catch((erreur) => {
    console.error(erreur); // Affiche : Erreur lors de l'opération.
    //catch est appelé lorsque la Promise est rejetée.Cela signifie si la Promise s'est terminée avec une erreur on exécute la fonction passée à catch.
    // Le paramètre de la fonction fléchée de catch est la raison pour laquelle la promesse a été rejetée c'est à dire la valeur passée à reject.
    // C'est pourquoi erreur ici est "Erreur lors de l'opération.".
  });
//On peut aligner plusieurs then pour chaîner des opérations asynchrones.
// Chaque then reçoit la valeur résolue du then précédent.
maPromise
  .then((valeur) => {
    console.log(valeur);
    return "Étape suivante";
  })
  .then((valeurSuivante) => {
    console.log(valeurSuivante); // Affiche : Étape suivante
  })
  .catch((erreur) => {
    console.error(erreur);
  });
// Les Promises permettent d'éviter le "callback hell" en chaînant les opérations de manière plus lisible.

